import XCTest

/// Run only against the separate DeviceTest app generated by prepare_device_tests.py.
@MainActor
final class WealthyDeviceUITests: XCTestCase {
    private let app = XCUIApplication(bundleIdentifier: "com.harrison.Wealthy.DeviceTest")
    override func setUpWithError() throws { continueAfterFailure = false }

    private func startEnglish() {
        app.launchArguments = ["-hasSelectedLanguage", "NO"]
        app.launch()
        let choice = app.buttons["onboarding.language.en"]
        XCTAssertTrue(choice.waitForExistence(timeout: 15), app.debugDescription)
        choice.tap()
        let currencySave = app.buttons["currency.selection.save"]
        if currencySave.waitForExistence(timeout: 4) { currencySave.tap() }
        XCTAssertTrue(app.tabBars.buttons["Wallets"].waitForExistence(timeout: 20), app.debugDescription)
    }
    private func enter(_ identifier: String, _ value: String) {
        let field = app.descendants(matching: .any)[identifier].firstMatch
        XCTAssertTrue(field.waitForExistence(timeout: 5), app.debugDescription)
        field.tap()
        let old = field.value as? String ?? ""
        field.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: old.count + 2))
        field.typeText(value)
    }
    private func capture(_ name: String) {
        let attachment = XCTAttachment(screenshot: app.screenshot())
        attachment.name = name; attachment.lifetime = .keepAlways
        add(attachment)
    }
    private func cashBalanceContains(_ amount: String) {
        let wallet = app.buttons["wallet.row.Cash"]
        XCTAssertTrue(wallet.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertTrue(wallet.label.contains(amount.replacingOccurrences(of: "-", with: "")) && (!amount.hasPrefix("-") || wallet.label.contains("-")), "Balance label: \(wallet.label)\n\(app.debugDescription)")
    }

    func test01BookkeepingPointsAndBackup() {
        startEnglish()
        app.buttons["expense.add"].tap()
        enter("expense.title", "Device lunch")
        enter("expense.amount", "1200")
        capture("expense-review")
        app.buttons["expense.save"].tap()
        app.tabBars.buttons["Wallets"].tap()
        cashBalanceContains("-1,200")
        capture("negative-provisional-cash")
        app.buttons["wallet.row.Cash"].tap()
        enter("wallet.amount", "5000")
        app.navigationBars.buttons["Save"].tap()
        cashBalanceContains("5,000")
        app.tabBars.buttons["Home"].tap()
        app.staticTexts["Device lunch"].tap()
        enter("expense.amount", "700")
        app.buttons["expense.cancel"].tap()
        app.tabBars.buttons["Wallets"].tap()
        cashBalanceContains("5,000")
        app.tabBars.buttons["Home"].tap()
        app.staticTexts["Device lunch"].tap()
        enter("expense.amount", "700")
        app.buttons["expense.save"].tap()
        app.tabBars.buttons["Wallets"].tap()
        cashBalanceContains("5,500")
        app.buttons["points.open"].tap()
        app.buttons["points.add"].tap()
        enter("points.name", "Device points")
        enter("points.number", "test-only")
        enter("points.amount", "900")
        app.navigationBars.buttons["Save"].tap()
        let card = app.buttons["points.row.Device points"]
        XCTAssertTrue(card.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertTrue(card.label.contains("900"), card.label)
        capture("point-card")
        card.tap()
        enter("points.amount", "1000")
        app.navigationBars.buttons["Cancel"].tap()
        XCTAssertTrue(card.label.contains("900"), card.label)
        app.navigationBars.buttons["Close"].tap()
        app.tabBars.buttons["Home"].tap()
        app.buttons["settings.open"].tap()
        app.buttons["backup.open"].tap()
        XCTAssertTrue(app.alerts.firstMatch.waitForExistence(timeout: 5), app.debugDescription)
        capture("backup-image-size-choice")
        XCTAssertTrue(app.alerts.buttons["Cancel"].exists)
        app.alerts.buttons["Cancel"].tap()
        app.navigationBars.buttons["Close"].tap()
        app.tabBars.buttons["Calendar"].tap(); capture("calendar")
        app.tabBars.buttons["Analysis"].tap(); capture("analysis")
    }

    func test02ActualChatLanguages() {
        startEnglish()
        app.buttons["chat.open"].tap()
        enter("chat.input", "今月の支出はいくらですか？")
        app.buttons["chat.send"].tap()
        let replies = app.staticTexts.matching(identifier: "chat.assistant")
        XCTAssertTrue(replies.firstMatch.waitForExistence(timeout: 90), app.debugDescription)
        let japanese = replies.allElementsBoundByIndex.last!.label
        XCTAssertFalse(japanese.hasPrefix("Error:"), japanese)
        XCTAssertNotNil(japanese.range(of: "[ぁ-んァ-ヶ]", options: .regularExpression), japanese)
        print("DEVICE_JAPANESE_REPLY: \(japanese)")
        capture("japanese-chat-in-english-ui")
        enter("chat.input", "How much spending is recorded this month?")
        app.buttons["chat.send"].tap()
        let next = NSPredicate { _, _ in replies.count >= 2 }
        XCTAssertEqual(XCTWaiter.wait(for: [XCTNSPredicateExpectation(predicate: next, object: nil)], timeout: 90), .completed)
        let english = replies.allElementsBoundByIndex.last!.label
        XCTAssertFalse(english.hasPrefix("Error:"), english)
        XCTAssertNil(english.range(of: "[ぁ-んァ-ヶ]", options: .regularExpression), english)
        XCTAssertTrue(english.range(of: "[A-Za-z]", options: .regularExpression) != nil, english)
        print("DEVICE_ENGLISH_REPLY: \(english)")
        capture("english-chat-after-japanese")
    }

    func test03LanguageSelectionAndPersistence() {
        let choices = ["en", "ja", "zh-Hans", "hi", "es", "ar", "fr", "id", "ko", "ru", "pt"]
        for language in choices {
            app.launchArguments = ["-hasSelectedLanguage", "NO"]
            app.launch()
            let choice = app.buttons["onboarding.language.\(language)"]
            XCTAssertTrue(app.collectionViews.firstMatch.waitForExistence(timeout: 15), app.debugDescription)
            for _ in 0..<6 where !choice.isHittable { app.collectionViews.firstMatch.swipeUp() }
            XCTAssertTrue(choice.isHittable, app.debugDescription)
            choice.tap()
            XCTAssertTrue(app.tabBars.firstMatch.waitForExistence(timeout: 20), app.debugDescription)
            capture("home-\(language)")
            app.terminate()
        }
        app.launchArguments = []
        app.launch()
        XCTAssertTrue(app.tabBars.firstMatch.waitForExistence(timeout: 20), app.debugDescription)
        XCTAssertFalse(app.buttons["onboarding.language.en"].exists)
        capture("persisted-portuguese-without-onboarding")
    }

    func test04SettingsLanguageAndRelaunch() {
        app.launchArguments = []
        app.launch()
        XCTAssertTrue(app.tabBars.firstMatch.waitForExistence(timeout: 20), app.debugDescription)
        XCTAssertFalse(app.buttons["onboarding.language.en"].exists)
        for choice in ["English", "हिन्दी", "العربية", "日本語"] {
            app.buttons["settings.open"].tap()
            let picker = app.buttons["settings.language"]
            XCTAssertTrue(picker.waitForExistence(timeout: 5), app.debugDescription)
            picker.tap()
            let option = app.buttons[choice]
            XCTAssertTrue(option.waitForExistence(timeout: 5), app.debugDescription)
            option.tap()
            app.buttons["settings.close"].tap()
            capture("settings-language-\(choice)")
        }
        app.terminate()
        app.launch()
        XCTAssertTrue(app.tabBars.buttons["ホーム"].waitForExistence(timeout: 20), app.debugDescription)
        XCTAssertFalse(app.buttons["onboarding.language.en"].exists)
        capture("settings-japanese-persisted-without-onboarding")
    }
    func test05MultipleCurrenciesAndFirstLaunchSequence() {
        app.launchArguments = ["-hasSelectedLanguage", "NO", "-hasSelectedCurrencies", "NO", "-selectedCurrency", "JPY", "-selectedCurrencies", "(JPY)"]
        app.launch()
        let language = app.buttons["onboarding.language.en"]
        XCTAssertTrue(language.waitForExistence(timeout: 15), app.debugDescription)
        XCTAssertFalse(app.buttons["currency.selection.save"].exists)
        language.tap()
        let save = app.buttons["currency.selection.save"]
        XCTAssertTrue(save.waitForExistence(timeout: 10), app.debugDescription)
        let search = app.searchFields.firstMatch
        XCTAssertTrue(search.exists, app.debugDescription)
        search.tap(); search.typeText("JPY")
        let yen = app.buttons["currency.toggle.JPY"]
        XCTAssertTrue(yen.waitForExistence(timeout: 5), app.debugDescription)
        yen.tap()
        XCTAssertFalse(save.isEnabled, "At least one currency is required")
        yen.tap()
        search.tap(); search.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: 3)); search.typeText("USD")
        let dollar = app.buttons["currency.toggle.USD"]
        XCTAssertTrue(dollar.waitForExistence(timeout: 5), app.debugDescription)
        dollar.tap(); capture("multiple-currency-first-launch")
        save.tap()
        XCTAssertTrue(app.tabBars.buttons["Home"].waitForExistence(timeout: 10), app.debugDescription)
        app.terminate(); app.launchArguments = []; app.launch()
        XCTAssertTrue(app.tabBars.buttons["Home"].waitForExistence(timeout: 20), app.debugDescription)
        XCTAssertFalse(app.buttons["onboarding.language.en"].exists)
        XCTAssertFalse(app.buttons["currency.selection.save"].exists)
        app.buttons["settings.open"].tap()
        app.buttons["settings.currency.default"].tap()
        let option = app.buttons.matching(NSPredicate(format: "label CONTAINS %@", "(USD)")).firstMatch
        XCTAssertTrue(option.waitForExistence(timeout: 5), app.debugDescription)
        option.tap(); app.buttons["settings.close"].tap()
        app.buttons["expense.add"].tap()
        enter("expense.title", "Device USD lunch")
        enter("expense.amount", "12.34")
        capture("usd-decimal-expense")
        app.buttons["expense.save"].tap()
        app.tabBars.buttons["Wallets"].tap()
        let wallet = app.buttons["wallet.row.Cash · USD"]
        XCTAssertTrue(wallet.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertTrue(wallet.label.contains("12.34") && wallet.label.contains("-"), wallet.label)
        cashBalanceContains("5,500")
        capture("separate-yen-dollar-wallets")
        app.tabBars.buttons["Home"].tap()
        app.buttons["Deposit"].tap()
        enter("deposit.amount", "100.00")
        app.buttons["deposit.save"].tap()
        app.tabBars.buttons["Wallets"].tap()
        XCTAssertTrue(wallet.waitForExistence(timeout: 5), app.debugDescription)
        XCTAssertTrue(wallet.label.contains("87.66"), wallet.label)
        cashBalanceContains("5,500")
        capture("usd-income-applied-once")
        app.tabBars.buttons["Analysis"].tap()
        XCTAssertTrue(app.descendants(matching: .any)["analysis.currency"].firstMatch.exists, app.debugDescription)
        XCTAssertTrue(app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "12.34")).firstMatch.exists, app.debugDescription)
        capture("usd-analysis")
        app.tabBars.buttons["Calendar"].tap(); capture("multiple-currency-calendar")
        app.tabBars.buttons["Home"].tap()
        app.buttons["settings.open"].tap()
        app.buttons["settings.currency.choose"].tap()
        let selectionSave = app.buttons["currency.selection.save"]
        XCTAssertTrue(selectionSave.waitForExistence(timeout: 5), app.debugDescription)
        app.searchFields.firstMatch.tap(); app.searchFields.firstMatch.typeText("USD")
        let selectedDollar = app.buttons["currency.toggle.USD"]
        XCTAssertTrue(selectedDollar.waitForExistence(timeout: 5))
        XCTAssertTrue(selectedDollar.isSelected, selectedDollar.debugDescription)
        app.buttons["currency.cancel"].tap(); app.buttons["settings.close"].tap()
        app.terminate(); app.launch()
        XCTAssertTrue(app.tabBars.buttons["Home"].waitForExistence(timeout: 20), app.debugDescription)
        XCTAssertFalse(app.buttons["currency.selection.save"].exists)
        XCTAssertTrue(app.staticTexts["Device USD lunch"].exists, app.debugDescription)
        capture("currencies-persisted-without-onboarding")
    }

    func test06ActualChatKeepsCurrenciesSeparate() {
        app.launchArguments = []
        app.launch()
        XCTAssertTrue(app.tabBars.buttons["Home"].waitForExistence(timeout: 20), app.debugDescription)
        XCTAssertFalse(app.buttons["onboarding.language.en"].exists)
        app.buttons["chat.open"].tap()
        let replies = app.staticTexts.matching(identifier: "chat.assistant")
        for question in [
            "今月の支出を通貨ごとに教えてください。通貨換算せず、通貨コードと金額を表示してください。",
            "What spending is recorded this month for each currency? Show currency codes and amounts without converting currencies."
        ] {
            let count = replies.count
            enter("chat.input", question); app.buttons["chat.send"].tap()
            let received = NSPredicate { _, _ in replies.count > count }
            XCTAssertEqual(XCTWaiter.wait(for: [XCTNSPredicateExpectation(predicate: received, object: nil)], timeout: 90), .completed)
            let reply = replies.allElementsBoundByIndex.last!.label
            XCTAssertFalse(reply.hasPrefix("Error:"), reply)
            // Localized currency names are valid labels; the amounts must stay separate and exact.
            let yenLabel = reply.contains("JPY") || reply.contains("円") || reply.localizedCaseInsensitiveContains("yen")
            let dollarLabel = reply.contains("USD") || reply.contains("ドル") || reply.localizedCaseInsensitiveContains("dollar")
            XCTAssertTrue(yenLabel && reply.range(of: "(?<![0-9])700(?![0-9])", options: .regularExpression) != nil, reply)
            XCTAssertTrue(dollarLabel && reply.range(of: "(?<![0-9])12\\.34(?![0-9])", options: .regularExpression) != nil, reply)
            if question.hasPrefix("今月") {
                XCTAssertNotNil(reply.range(of: "[ぁ-んァ-ヶ]", options: .regularExpression), reply)
            } else {
                XCTAssertNil(reply.range(of: "[ぁ-んァ-ヶ]", options: .regularExpression), reply)
            }
            print("DEVICE_MULTICURRENCY_REPLY: \(reply)")
            capture(question.hasPrefix("今月") ? "japanese-multiple-currency-chat" : "english-multiple-currency-chat")
        }
    }

}
